<?php
declare(strict_types=1);
require_once __DIR__ . '/../../includes/functions.php'; require_once __DIR__ . '/../../auth/guard.php'; require_once __DIR__ . '/../../config/database.php'; require_once __DIR__ . '/../../includes/module2_helpers.php'; requireAdmin();
$id=(int)($_GET['id']??0); if($id<=0){setFlash('error','Mã căn hộ không hợp lệ.');redirect('/admin/can-ho/index.php');}
$stmt=$pdo->prepare('SELECT * FROM CanHo WHERE MaCanHo=:id');$stmt->execute([':id'=>$id]);$data=$stmt->fetch();if(!$data){setFlash('error','Không tìm thấy căn hộ.');redirect('/admin/can-ho/index.php');}$types=$pdo->query('SELECT MaLoai,TenLoai FROM LoaiCanHo ORDER BY TenLoai')->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){module2_require_csrf();$data['SoPhong']=trim((string)($_POST['SoPhong']??''));$data['MaLoai']=(int)($_POST['MaLoai']??0);$data['DienTich']=trim((string)($_POST['DienTich']??''));$data['GiaThue']=trim((string)($_POST['GiaThue']??''));$data['TrangThai']=(string)($_POST['TrangThai']??'');$data['MoTa']=trim((string)($_POST['MoTa']??''));if($data['SoPhong']===''||mb_strlen($data['SoPhong'])>20)$errors[]='Số phòng không hợp lệ.';if($data['MaLoai']<=0)$errors[]='Loại căn không hợp lệ.';if($data['DienTich']===''||!is_numeric($data['DienTich'])||(float)$data['DienTich']<=0)$errors[]='Diện tích phải > 0.';if($data['GiaThue']===''||!is_numeric($data['GiaThue'])||(float)$data['GiaThue']<0)$errors[]='Giá thuê phải >= 0.';if(!in_array($data['TrangThai'],['Trống','Đang thuê','Bảo trì'],true))$errors[]='Trạng thái không hợp lệ.';if(mb_strlen($data['MoTa'])>255)$errors[]='Mô tả tối đa 255 ký tự.';$s=$pdo->prepare('SELECT COUNT(*) FROM CanHo WHERE SoPhong=:sp AND MaCanHo<>:id');$s->execute([':sp'=>$data['SoPhong'],':id'=>$id]);if((int)$s->fetchColumn())$errors[]='Số phòng đã tồn tại.';if(!$errors){try{$s=$pdo->prepare('UPDATE CanHo SET SoPhong=:sp,MaLoai=:loai,DienTich=:dt,GiaThue=:gia,TrangThai=:tt,MoTa=:mota WHERE MaCanHo=:id');$s->execute([':sp'=>$data['SoPhong'],':loai'=>$data['MaLoai'],':dt'=>(float)$data['DienTich'],':gia'=>(float)$data['GiaThue'],':tt'=>$data['TrangThai'],':mota'=>$data['MoTa']?:null,':id'=>$id]);setFlash('success','Cập nhật căn hộ thành công.');redirect('/admin/can-ho/detail.php?id='.$id);}catch(PDOException $e){error_log($e->getMessage());$errors[]='Không thể cập nhật căn hộ.';}}}
$title='Sửa căn hộ';require_once __DIR__ . '/../../includes/header.php';
?><div class="page-header"><div><h1>Sửa căn hộ #<?=$id?></h1></div><a class="btn btn-light" href="detail.php?id=<?=$id?>">Quay lại</a></div><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?><form method="post" class="form-card"><input type="hidden" name="csrf_token" value="<?=e(module2_csrf_token())?>"><div class="form-grid"><div class="form-group"><label>Số phòng *</label><input name="SoPhong" value="<?=e($data['SoPhong'])?>" maxlength="20" required></div><div class="form-group"><label>Loại *</label><select name="MaLoai"><?php foreach($types as $t):?><option value="<?=$t['MaLoai']?>" <?=$data['MaLoai']==(int)$t['MaLoai']?'selected':''?>><?=e($t['TenLoai'])?></option><?php endforeach;?></select></div><div class="form-group"><label>Diện tích *</label><input type="number" name="DienTich" min=".01" step=".01" value="<?=e($data['DienTich'])?>" required></div><div class="form-group"><label>Giá thuê *</label><input type="number" name="GiaThue" min="0" step=".01" value="<?=e($data['GiaThue'])?>" required></div><div class="form-group"><label>Trạng thái</label><select name="TrangThai"><?php foreach(['Trống','Đang thuê','Bảo trì'] as $s):?><option <?=$data['TrangThai']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div></div><div class="form-group"><label>Mô tả</label><textarea name="MoTa" maxlength="255" rows="4"><?=e($data['MoTa']??'')?></textarea></div><div class="form-actions"><button class="btn btn-primary">Lưu</button><a class="btn btn-light" href="detail.php?id=<?=$id?>">Hủy</a></div></form><?php require_once __DIR__ . '/../../includes/footer.php'; ?>